WITH eligible AS (SELECT s.* FROM customers s WHERE NOT EXISTS (SELECT 1 FROM orders c WHERE c.customer_id = s.id AND c.order_date < s.signup_date)), kept AS (SELECT s.* FROM eligible s WHERE EXISTS (SELECT 1 FROM subscriptions c WHERE c.customer_id = s.id AND c.start_date > '2025-01-03')), with_last AS (SELECT s.*, top1.start_date FROM kept s LEFT JOIN LATERAL (SELECT c.start_date FROM subscriptions c WHERE c.customer_id = s.id ORDER BY c.start_date DESC, c.id DESC LIMIT 1) top1 ON TRUE), kept_customers AS (SELECT s.* FROM with_last s WHERE EXISTS (SELECT 1 FROM sessions c WHERE c.customer_id = s.id AND c.started_at >= s.start_date)), latest_match AS (SELECT s.*, latest.session_browser FROM kept_customers s JOIN LATERAL (SELECT c.browser AS session_browser FROM sessions c WHERE c.customer_id = s.id AND c.started_at <= s.start_date ORDER BY c.started_at DESC, c.id DESC LIMIT 1) latest ON TRUE), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY country ORDER BY age DESC NULLS FIRST, id) AS rank_in_group FROM latest_match QUALIFY rank_in_group = 1) SELECT * FROM (SELECT segment, country, session_browser, credit_limit FROM deduped) src PIVOT (SUM(credit_limit) AS total, COUNT(1) AS cnt FOR session_browser IN ('Firefox' AS firefox, 'Edge' AS edge));
